        $this->load->model('coupons_model');
    }

    public function index()
    {
        $data['coupons'] = $this->coupons_model->get_coupons();
        $this->load->view('ecommerce/coupons', \($data);
    }

    public function edit_coupon($id)
    {
        $data['coupons'] = $this->coupons_model->get_coupons();
        $data['coupon'] = $this->coupons_model->get_coupon($id);
        $this->load->view('ecommerce/coupons', $data);
    }

    public function delete_coupon($id)
    {
        $this->coupons_model->delete_coupon($id);
        set_alert('danger', 'Cupom deletado com sucesso!');
        redirect(admin_url('ecommerce/coupons'));
    }

    public function save_coupon()
    {
        // Validação de campos obrigatórios
        $required_fields = ['code', 'discount_type', 'discount_value', 'valid_from', 'valid_to', 'for_new_users', 'is_reusable'];
        $input_data = array_intersect_key($this->input->post(), array_flip($required_fields));

        if (empty($input_data['code']) || empty($input_data['discount_type']) || 
            empty($input_data['discount_value']) || empty($input_data['valid_from']) ||
            empty($input_data['valid_to']))
        {
            set_alert('danger', 'Por favor, preencha todos os campos obrigatórios.');
            redirect(admin_url('ecommerce/coupons'));
        }

        // Validação e conversão de datas
        $data = [
            'code' => strtolower($input_data['code']),  // Teste sensibilidade
            'discount_type' => $input_data['discount_type'],
            'discount_value' => $input_data['discount_value'],
            'valid_from' => date('Y-m-d H:i:s', strtotime($input_data['valid_from'])),
            'valid_to' => date('Y-m-d H:i:s', strtotime($input_data['valid_to'])),
            'for_new_users' => ($input_data['for_new_users'] == 1) ? 1 : 0,
            'is_reusable' => ($input_data['is_reusable'] == 1) ? 1 : 0
        ];

        // Verificação de cupom duplicado na base de dados
        $existing_coupon = $this->coupons_model->get_coupon_by_code($data['code']);

        // Condição de verificação: se cupom existiu e é diferente ou cupom novo
        if ($existing_coupon && 
            (($id && $existing_coupon->id != $id) || !$id))
        {
            $is_new_coupon = !$id;
            $error_message = $is_new_coupon 
                ? 'O código do cupom já está em uso. Por favor, escolha um código diferente.' 
                : 'Ocupado por cupom existente.';

            set_alert('danger', $error_message);
            redirect($_SERVER['HTTP_REFERER']);
        }

        // Processamento do cupom
        if ($id) {
            $this->coupons_model->update_coupon($id, $data);
        } else {
            $this->coupons_model->insert_coupon($data);
        }

        // Mensagem de sucesso
        set_alert('success', 'Cupom salvo com sucesso!');
        redirect(admin_url('ecommerce/coupons'));
    }
}
